-- Reviewed catalog data from the supplied 115-school DOCX; URLs are not a promise of public accessibility.
ALTER TABLE campus_documents DROP CONSTRAINT campus_documents_collection_check;
ALTER TABLE campus_documents ADD CONSTRAINT campus_documents_collection_check CHECK (collection IN ('schools','sources','items','user_profiles','web_ai_tasks','web_ai_accounts','school_sync','school_requests'));
CREATE INDEX campus_school_requests_owner ON campus_documents ((body->>'owner'),(body->>'createdAt')) WHERE collection='school_requests';
